var l=n=>Number.isFinite(n)?Math.max(0,Math.min(100,n)):50;function m(n){if(!n)return null;let[e="",t=""]=n.split(",");if(e.trim()===""||t.trim()==="")return null;let r=Number(e),y=Number(t);return!Number.isFinite(r)||!Number.isFinite(y)?null:{x:l(r),y:l(y)}}function a(n,e="free",t=12){let r=n.length;if(r===0)return[];if(e==="free")return n.map(u=>m(u)??{x:50,y:50});let y=100-t*2;return n.map((u,i)=>{let o=r===1?.5:i/(r-1),x=t+y*o;return e==="row"?{x,y:50}:{x:50,y:x}})}function c(n,e,t=6){let r=e.x-n.x,y=e.y-n.y,u=Math.hypot(r,y);if(u===0)return{x1:n.x,y1:n.y,x2:e.x,y2:e.y,mx:n.x,my:n.y};let i=Math.min(t,u/3),o=r/u,x=y/u;return{x1:n.x+o*i,y1:n.y+x*i,x2:e.x-o*i,y2:e.y-x*i,mx:(n.x+e.x)/2,my:(n.y+e.y)/2}}export{a as arrange,c as edgeGeometry,m as parsePoint};
